import datetime
import jsonpickle
import os
import shutil
from IQCommon.exception import get_traceback_message
from IQCommon.logger import strategy_log, system_log
from IQCommon.util.trade_info_utils import set_trade_stop_status
from IQEngine.core.events import Event, EventEnum
from IQEngine.interface import AbstractPlugin
from IQEngine.plugins.plugin_system_persist.json_persistance import JsonPersistance
from IQEngine.plugins.plugin_system_persist.recorder import CsvRecorder
from IQEngine.utils.datetime_func import convert_date_to_date_int
from IQEngine.utils.i18n import get_local_text as _
class ObjectPersistancePlugin(AbstractPlugin):
    _meta = None
    _engine = None
    _recorder = None
    _persist_provider = None
    def setup(self, engine):
        self._engine = engine
        self._persist_provider = None
        try:
            try:
                strategy_log.warning('开始清理持久化数据，全局对象g中变量将会被清空')
                shutil.rmtree(dir_path)
            except BaseException: system_log.error('清理持久化数据失败，错误原因：%s' % get_traceback_message())
            else:
                if (not os.path.exists(dir_path)):
                    os.makedirs(dir_path)
                persist_provider = JsonPersistance(dir_path)
                self._recorder = CsvRecorder(dir_path)
                if persist_provider:
                    self._persist_provider = persist_provider
                    self._engine.event_bus.append_listener(EventEnum.SYSTEM_INIT, self.on_increment_handle)
            return None
            persist_provider = None
            persist_enable = engine.config.strategy.persist.enable
            if (not persist_enable):
                return None
            else:
                persist_record = engine.config.strategy.persist.mod.recorder
                if (persist_record == 'FileRecorder'):
                    dir_path = engine.config.strategy.persist.mod.dir_path
                    auto_restart = engine.config.strategy.persist.get('auto_restart', '0')
                    rebuild_delete_persist = engine.config.strategy.persist.get('rebuild_delete_persist', '0')
                    if (auto_restart == '1' and rebuild_delete_persist == '1' and os.path.exists(dir_path)):
                        pass
        except BaseException:
            strategy_log.error(_('持久化插件加载失败，错误原因：{}'.format(get_traceback_message())))
            return None
    def generate_meta(self):
        self._meta = {'start_date': convert_date_to_date_int(self._engine.config.strategy.start_date), 'end_date': convert_date_to_date_int(self._engine.config.strategy.end_date), 'last_calendar_dt': None, 'last_run_time': datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}
    def flush_meta(self):
        self._meta['last_calendar_dt'] = convert_date_to_date_int(self._engine.calendar_dt)
        self._engine.persist_provider.store('meta', jsonpickle.encode(self._meta))
    def can_resume_strategy(self, persist_meta, data_proxy):
        if (persist_meta['start_date'] != self._meta['start_date']):
            raise RuntimeError(_('持久化恢复时，策略运行起始时间不一致，原start_date={}，现start_date={}'.format(persist_meta['start_date'], self._meta['start_date'])))
        elif (persist_meta['last_calendar_dt'] is None):
            return False
        elif (persist_meta['last_calendar_dt'] > self._meta['end_date']):
            raise RuntimeError(_('持久化恢复时，策略的运行的结束时间{}小于持久化存储的结束时间{}'.format(self._meta['end_date'], persist_meta['last_calendar_dt'])))
        elif (persist_meta['last_calendar_dt'] == self._meta['end_date']):
            return False
        else:
            next_start_date = data_proxy.get_next_trading_date(persist_meta['last_calendar_dt'], 1)
            next_start_date = convert_date_to_date_int(next_start_date)
            if (next_start_date > self._meta['end_date']):
                return False
            else:
                return True
    def on_increment_handle(self, event):
        self.generate_meta()
        try:
            json_str = self._persist_provider.get_data('meta')
            if (json_str is None):
                set_trade_stop_status(self._engine.config.strategy.trade_id)
                system_log.error('获取持久化对象meta失败，终止交易')
                self._engine.event_bus.publish_event(Event(EventEnum.SYSTEM_EXIT))
                return None
            else:
                persist_meta = jsonpickle.decode(json_str)
                if self.can_resume_strategy(persist_meta, self._engine.data_proxy):
                    next_start_date = self._engine.data_proxy.get_next_trading_date(persist_meta['last_calendar_dt'], 1)
                    self._engine.config.strategy.start_date = next_start_date
                    self._engine.set_persist_provider(self._persist_provider)
                    self._engine.event_bus.append_listener(EventEnum.ORDER_TRADE, self.on_trade)
                    self._engine.event_bus.append_listener(EventEnum.POST_SETTLEMENT, self.on_settlement)
                    self._engine.event_bus.append_listener(EventEnum.PRE_BEFORE_TRADING_START, self.on_pre_before_trading_start)
                    self._engine.event_bus.append_listener(EventEnum.BEFORE_TRADING_START, self.on_before_trading_start)
                return None
        except FileNotFoundError:
            system_log.debug(_('策略第一次进行持久化操作'))
            self._engine.set_persist_provider(self._persist_provider)
            self._engine.event_bus.append_listener(EventEnum.ORDER_TRADE, self.on_trade)
            self._engine.event_bus.append_listener(EventEnum.POST_SETTLEMENT, self.on_settlement)
            self._engine.event_bus.append_listener(EventEnum.PRE_BEFORE_TRADING_START, self.on_pre_before_trading_start)
            self._engine.event_bus.append_listener(EventEnum.BEFORE_TRADING_START, self.on_before_trading_start)
            return None
        except BaseException:
            set_trade_stop_status(self._engine.config.strategy.trade_id)
            strategy_log.error(_('策略持久化获取失败，错误原因：{}'.format(get_traceback_message())))
            self._engine.event_bus.publish_event(Event(EventEnum.SYSTEM_EXIT))
            return None
    def on_trade(self, event):
        trade = event.trade
        self._recorder.append_trade(trade)
    def on_settlement(self, event):
        calendar_dt = self._engine.calendar_dt
        portfolio = self._engine.portfolio
        bm_portfolio = self._engine.benchmark_portfolio
        self.do_persist()
        self._recorder.append_portfolio(calendar_dt, portfolio, bm_portfolio)
    def on_pre_before_trading_start(self, event):
        self.do_persist()
    def on_before_trading_start(self, event):
        self.do_persist()
    def do_persist(self):
        self.flush_meta()
        self._engine.persist_helper.flush()
        self._persist_provider.persist()
    def cleanup(self, exit_code, exception=None):
        if self._persist_provider:
            self._persist_provider.persist()
        if self._recorder:
            self._recorder.flush()
            self._recorder.close()
            return None
    def interface(self):
        return self
def load_plugin():
    return ObjectPersistancePlugin()
